  cells_size optc = 40%nat ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> dof_core c c1 ->
  evt bsegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz (Z.shiftr ff 3 + 2147450880)) s4x s5x s6x s7x s8x s9x s10x (wz ASHADOW_BASE) t3 t4 t5 t6)
        F (Z_to_bv 64 0xd5b9c) fc None m1 (seg_rom bsegs)).
