Lemma conn_all : forall n, CONN_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros itc vq vl err pad7o. intros until h3. intros L PURE DC Q1 Q2 Q3 Q4 QM ERR. exfalso. cbn [Z.of_nat] in QM. clear - Q1 Q2 Q3 Q4 QM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply conn_step. exact IH.
Qed.

Lemma m11_lit : Z_to_bv 64 (-11) = Z_to_bv 64 18446744073709551605.
Proof. apply bv_eq. vm_compute. reflexivity. Qed.

